#!/usr/bin/env node
/**
 * slack_call.cjs — call the Slack Web API from the command line.
 *
 * Usage:
 *   SLACK_TOKEN=xoxb-... node slack_call.cjs <method> ['{"json":"args"}'] [--paginate] [--limit N] [--verbose]
 *
 * Examples:
 *   node slack_call.cjs auth.test
 *   node slack_call.cjs chat.postMessage '{"channel":"C12345","text":"Hello from Gemini CLI!"}'
 *   node slack_call.cjs conversations.history '{"channel":"C12345","limit":10}'
 *   node slack_call.cjs users.list '{"limit":100}' --paginate
 *
 * Prints the JSON response on stdout. Diagnostics go to stderr.
 * Exits non-zero with a plain-language error when the API call fails.
 */
'use strict';

const BASE_URL = 'https://slack.com/api/';

const USAGE = `Usage:
  SLACK_TOKEN=xoxb-... node slack_call.cjs <method> [json-args] [--paginate] [--limit N] [--verbose]

Examples:
  node slack_call.cjs auth.test
  node slack_call.cjs chat.postMessage '{"channel":"C12345","text":"Hello from Gemini CLI!"}'
  node slack_call.cjs conversations.history '{"channel":"C12345","limit":10}'
  node slack_call.cjs users.list '{"limit":100}' --paginate

Options:
  --paginate      Follow response_metadata.next_cursor and merge result arrays.
  --limit N       Maximum pages when paginating (default 20).
  --verbose       Print HTTP status and request details to stderr.
  --help, -h      Show this help.`;

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function parseArgs(argv) {
  // Drop a script path if the runner passes one as an argument.
  const args = argv.filter((a) => !a.endsWith('.cjs'));
  const parsed = { method: null, jsonArgs: {}, paginate: false, limit: 20, verbose: false };
  const positional = [];
  for (let i = 0; i < args.length; i++) {
    const a = args[i];
    if (a === '--help' || a === '-h') {
      console.log(USAGE);
      process.exit(0);
    } else if (a === '--paginate') {
      parsed.paginate = true;
    } else if (a === '--verbose') {
      parsed.verbose = true;
    } else if (a === '--limit') {
      const n = parseInt(args[++i], 10);
      if (!Number.isInteger(n) || n < 1) {
        console.error('Error: --limit must be a positive integer.');
        process.exit(1);
      }
      parsed.limit = n;
    } else if (a.startsWith('--')) {
      console.error(`Error: unknown option "${a}".\n\n${USAGE}`);
      process.exit(1);
    } else {
      positional.push(a);
    }
  }
  if (positional.length === 0) {
    console.error(`Error: missing Slack API method.\n\n${USAGE}`);
    process.exit(1);
  }
  parsed.method = positional[0];
  if (!/^[a-z]+\.[A-Za-z0-9_]+$/.test(parsed.method)) {
    console.error(`Error: "${parsed.method}" is not a valid Slack API method (expected e.g. chat.postMessage).`);
    process.exit(1);
  }
  if (positional.length > 1) {
    try {
      const parsedJson = JSON.parse(positional[1]);
      if (parsedJson === null || typeof parsedJson !== 'object' || Array.isArray(parsedJson)) {
        throw new Error('must be a JSON object');
      }
      parsed.jsonArgs = parsedJson;
    } catch (err) {
      console.error(`Error: json-args must be a valid JSON object (${err.message}).\n\n${USAGE}`);
      process.exit(1);
    }
  }
  if (positional.length > 2) {
    console.error(`Error: too many positional arguments.\n\n${USAGE}`);
    process.exit(1);
  }
  return parsed;
}

async function post(method, body, { token, verbose, retries = 3 }) {
  const url = BASE_URL + method;
  let lastError = '';
  for (let attempt = 1; attempt <= retries; attempt++) {
    if (verbose) console.error(`Slack API: POST ${url} (attempt ${attempt}/${retries})`);
    let res;
    try {
      res = await fetch(url, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
    } catch (err) {
      lastError = `network error: ${err.message}`;
      await sleep(1000 * attempt);
      continue;
    }
    if (res.status === 429) {
      const retryAfter = parseFloat(res.headers.get('retry-after') || '1');
      lastError = `rate limited (HTTP 429), retrying after ${retryAfter}s`;
      if (verbose) console.error(`Slack API: ${lastError}`);
      await sleep((retryAfter + 0.5) * 1000);
      continue;
    }
    const text = await res.text();
    let json;
    try {
      json = JSON.parse(text);
    } catch {
      lastError = `HTTP ${res.status}: non-JSON response from Slack`;
      await sleep(1000 * attempt);
      continue;
    }
    if (json.ok === false) {
      if (json.error === 'rate_limited') {
        const retryAfter = typeof json.retry_after === 'number' ? json.retry_after : 1;
        lastError = `rate limited (ok:false), retrying after ${retryAfter}s`;
        if (verbose) console.error(`Slack API: ${lastError}`);
        await sleep((retryAfter + 0.5) * 1000);
        continue;
      }
      const detail = json.needed ? ` (needed: ${json.needed}, provided: ${json.provided || 'none'})` : '';
      throw new Error(`Slack API error: ${json.error}${detail}`);
    }
    if (res.status !== 200) {
      lastError = `HTTP ${res.status}`;
      await sleep(1000 * attempt);
      continue;
    }
    return json;
  }
  throw new Error(lastError || 'request failed after retries');
}

function mergePages(pages) {
  const merged = {};
  const arrayKeys = new Set();
  for (const page of pages) {
    for (const [key, value] of Object.entries(page)) {
      if (Array.isArray(value)) arrayKeys.add(key);
    }
  }
  for (const key of arrayKeys) {
    merged[key] = [];
    for (const page of pages) {
      if (Array.isArray(page[key])) merged[key].push(...page[key]);
    }
  }
  for (const page of pages) {
    for (const [key, value] of Object.entries(page)) {
      if (!Array.isArray(value) && !(key in merged)) merged[key] = value;
    }
  }
  delete merged.response_metadata; // pagination is complete; the cursor is no longer meaningful
  merged._pages = pages.length;
  return merged;
}

function finalizeOutput(output) {
  const text = JSON.stringify(output, null, 2);
  const max = 150000;
  if (text.length <= max) return text;
  const note =
    `full response was ${text.length} chars; re-run with a smaller limit or the returned cursor to page further`;
  return JSON.stringify({ _truncated: true, _note: note, _partial: text.slice(0, max) }, null, 2);
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const token = process.env.SLACK_TOKEN;
  if (!token) {
    console.error('Error: SLACK_TOKEN environment variable is not set.\n\n' + USAGE);
    process.exit(1);
  }
  if (typeof fetch !== 'function') {
    console.error('Error: global fetch is unavailable. Run this script with Node.js 18 or newer.');
    process.exit(1);
  }

  const pages = [];
  let cursor = args.jsonArgs.cursor;
  let pageCount = 0;
  do {
    const body = { ...args.jsonArgs };
    if (cursor) body.cursor = cursor;
    const page = await post(args.method, body, { token, verbose: args.verbose });
    pages.push(page);
    pageCount += 1;
    const nextCursor = page.response_metadata && page.response_metadata.next_cursor;
    cursor = args.paginate && nextCursor ? nextCursor : '';
    if (cursor && pageCount >= args.limit) {
      console.error(`Slack API: stopped pagination after ${args.limit} pages (more results remain).`);
      cursor = '';
    }
    if (cursor) await sleep(1100); // be polite to Slack's per-method rate limits
  } while (cursor);

  const output = args.paginate && pages.length > 1 ? mergePages(pages) : pages[0];
  console.log(finalizeOutput(output));
}

main().catch((err) => {
  console.error(`Error: ${err.message}`);
  process.exit(1);
});

#!/usr/bin/env node
/**
 * package_skill.cjs — validate a skill folder and package it into a .skill file
 * (a zip archive with the skill folder at its root).
 *
 * Usage:
 *   node package_skill.cjs <skill-folder> [output-dir]
 *
 * Validates: frontmatter (name + description), naming conventions, no TODO
 * placeholders, referenced resources exist. Then writes <name>.skill and
 * round-trip verifies the archive by re-parsing its central directory.
 */
'use strict';

const fs = require('fs');
const path = require('path');
const zlib = require('zlib');

const NAME_RE = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

function parseFrontmatter(text) {
  const m = /^---\r?\n([\s\S]*?)\r?\n---\r?\n?/.exec(text);
  if (!m) return null;
  const fm = {};
  for (const line of m[1].split(/\r?\n/)) {
    const idx = line.indexOf(':');
    if (idx === -1) continue;
    const key = line.slice(0, idx).trim();
    const value = line.slice(idx + 1).trim().replace(/^["']|["']$/g, '');
    if (key) fm[key] = value;
  }
  return fm;
}

function validate(folder) {
  const errors = [];
  const warnings = [];

  const skillName = path.basename(folder);
  if (!NAME_RE.test(skillName)) {
    errors.push(`skill folder name "${skillName}" must be lowercase letters, digits, and hyphens only`);
  }
  if (skillName.length >= 64) {
    errors.push(`skill folder name "${skillName}" must be under 64 characters`);
  }

  const skillMdPath = path.join(folder, 'SKILL.md');
  if (!fs.existsSync(skillMdPath)) {
    errors.push('SKILL.md is missing');
    return { errors, warnings };
  }
  const skillMd = fs.readFileSync(skillMdPath, 'utf8');
  const fm = parseFrontmatter(skillMd);
  if (!fm) {
    errors.push('SKILL.md has no YAML frontmatter (must start with "---" and end with "---")');
  } else {
    if (!fm.name) errors.push('frontmatter is missing required field: name');
    else if (fm.name !== skillName) errors.push(`frontmatter name "${fm.name}" does not match folder name "${skillName}"`);
    else if (!NAME_RE.test(fm.name)) errors.push(`name "${fm.name}" must be lowercase letters, digits, and hyphens only`);
    if (!fm.description) errors.push('frontmatter is missing required field: description');
    else if (fm.description.length < 30) errors.push('description is too short; describe what the skill does and when to use it');
    else if (!/use when/i.test(fm.description)) warnings.push('description does not mention "Use when..." — add triggering context');
  }
  if (/TODO|TBD|PLACEHOLDER/i.test(skillMd)) {
    errors.push('SKILL.md still contains TODO/TBD/PLACEHOLDER markers');
  }

  // Only expected top-level entries.
  for (const entry of fs.readdirSync(folder)) {
    if (!['SKILL.md', 'scripts', 'references', 'assets'].includes(entry)) {
      warnings.push(`unexpected top-level entry "${entry}" (skills should only contain SKILL.md, scripts/, references/, assets/)`);
    }
  }

  // References to bundled resources should resolve.
  const refRe = /(scripts|references|assets)\/[\w.\-]+/g;
  let m;
  while ((m = refRe.exec(skillMd)) !== null) {
    const rel = m[0];
    if (!fs.existsSync(path.join(folder, rel))) {
      warnings.push(`SKILL.md references "${rel}" but that file does not exist`);
    }
  }

  return { errors, warnings };
}

// ---------------------------------------------------------------------------
// ZIP writer (deflate, no external dependencies)
// ---------------------------------------------------------------------------

function crc32(buf) {
  let crc = 0xffffffff;
  for (let i = 0; i < buf.length; i++) {
    crc = CRC_TABLE[(crc ^ buf[i]) & 0xff] ^ (crc >>> 8);
  }
  return (crc ^ 0xffffffff) >>> 0;
}

const CRC_TABLE = (() => {
  const table = new Int32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) {
      c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    }
    table[n] = c;
  }
  return table;
})();

function toDosDateTime(date) {
  const dosTime = (date.getHours() << 11) | (date.getMinutes() << 5) | Math.floor(date.getSeconds() / 2);
  const dosDate = ((date.getFullYear() - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate();
  return { dosTime, dosDate };
}

function buildZip(entries) {
  const { dosTime, dosDate } = toDosDateTime(new Date());
  const chunks = [];
  const centralChunks = [];
  let offset = 0;

  for (const entry of entries) {
    const nameBuf = Buffer.from(entry.name, 'utf8');
    const data = entry.data;
    const crc = crc32(data);
    const comp = zlib.deflateRawSync(data, { level: 9 });

    const local = Buffer.alloc(30);
    local.writeUInt32LE(0x04034b50, 0); // local file header signature
    local.writeUInt16LE(20, 4); // version needed
    local.writeUInt16LE(0x0800, 6); // flags: UTF-8 names
    local.writeUInt16LE(8, 8); // method: deflate
    local.writeUInt16LE(dosTime, 10);
    local.writeUInt16LE(dosDate, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(comp.length, 18);
    local.writeUInt32LE(data.length, 22);
    local.writeUInt16LE(nameBuf.length, 26);
    local.writeUInt16LE(0, 28); // extra length
    chunks.push(local, nameBuf, comp);

    const central = Buffer.alloc(46);
    central.writeUInt32LE(0x02014b50, 0); // central directory signature
    central.writeUInt16LE(20, 4); // version made by
    central.writeUInt16LE(20, 6); // version needed
    central.writeUInt16LE(0x0800, 8); // flags: UTF-8 names
    central.writeUInt16LE(8, 10); // method: deflate
    central.writeUInt16LE(dosTime, 12);
    central.writeUInt16LE(dosDate, 14);
    central.writeUInt32LE(crc, 16);
    central.writeUInt32LE(comp.length, 20);
    central.writeUInt32LE(data.length, 24);
    central.writeUInt16LE(nameBuf.length, 28);
    central.writeUInt16LE(0, 30); // extra length
    central.writeUInt16LE(0, 32); // comment length
    central.writeUInt16LE(0, 34); // disk number
    central.writeUInt16LE(0, 36); // internal attrs
    central.writeUInt32LE(0, 38); // external attrs
    central.writeUInt32LE(offset, 42); // local header offset
    centralChunks.push(central, nameBuf);

    offset += 30 + nameBuf.length + comp.length;
  }

  const centralSize = centralChunks.reduce((n, c) => n + c.length, 0);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0); // end of central directory signature
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(centralSize, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);

  return Buffer.concat([...chunks, ...centralChunks, eocd]);
}

function verifyZip(buf) {
  const eocdPos = buf.lastIndexOf(Buffer.from([0x50, 0x4b, 0x05, 0x06]));
  if (eocdPos < 0) throw new Error('EOCD record not found — not a valid zip');
  const count = buf.readUInt16LE(eocdPos + 10);
  let p = buf.readUInt32LE(eocdPos + 16);
  const names = [];
  for (let i = 0; i < count; i++) {
    if (buf.readUInt32LE(p) !== 0x02014b50) throw new Error(`bad central directory header at entry ${i}`);
    const nameLen = buf.readUInt16LE(p + 28);
    const extraLen = buf.readUInt16LE(p + 30);
    const commentLen = buf.readUInt16LE(p + 32);
    names.push(buf.slice(p + 46, p + 46 + nameLen).toString('utf8'));
    p += 46 + nameLen + extraLen + commentLen;
  }
  return names;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------

function walk(dir, root, out = []) {
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    const rel = path.relative(root, full).split(path.sep).join('/');
    if (entry.isDirectory()) walk(full, root, out);
    else out.push(rel);
  }
  return out;
}

function main() {
  const args = process.argv.slice(2).filter((a) => !a.endsWith('.cjs'));
  if (args.length < 1) {
    console.error('Usage: node package_skill.cjs <skill-folder> [output-dir]');
    process.exit(1);
  }
  const folder = path.resolve(args[0]);
  const outDir = path.resolve(args[1] || './dist');
  const skillName = path.basename(folder);

  if (!fs.existsSync(folder) || !fs.statSync(folder).isDirectory()) {
    console.error(`Error: "${folder}" is not a directory`);
    process.exit(1);
  }

  const { errors, warnings } = validate(folder);
  for (const w of warnings) console.warn(`Warning: ${w}`);
  if (errors.length > 0) {
    for (const e of errors) console.error(`Error: ${e}`);
    console.error('Validation failed — no package created.');
    process.exit(1);
  }

  const files = walk(folder, folder);
  if (files.length === 0) {
    console.error('Error: skill folder is empty');
    process.exit(1);
  }

  const entries = files
    .sort()
    .map((rel) => ({ name: `${skillName}/${rel}`, data: fs.readFileSync(path.join(folder, rel)) }));

  const zip = buildZip(entries);
  fs.mkdirSync(outDir, { recursive: true });
  const outFile = path.join(outDir, `${skillName}.skill`);
  fs.writeFileSync(outFile, zip);

  const verified = verifyZip(zip);
  console.log(`Validated and packaged: ${outFile}`);
  console.log(`Files (${verified.length}):`);
  for (const name of verified) console.log(`  ${name}`);
  console.log(`Size: ${zip.length} bytes`);
}

main();

